import{PDFDocument,PDFName,PDFNumber,PDFHexString}from"pdf-lib";
import initSqlJs from"sql.js";
import*as duckdb from"@duckdb/duckdb-wasm";
let sqlPromise,sqlLocation;
const sql=(wasmPath="/client-tools/vendor/sql-wasm.wasm")=>{if(!sqlPromise||sqlLocation!==wasmPath){sqlLocation=wasmPath;sqlPromise=initSqlJs({locateFile:name=>name.endsWith(".wasm")?wasmPath:"/client-tools/vendor/"+name})}return sqlPromise};
const qid=s=>'"'+String(s).replace(/"/g,'""')+'"';
export async function editPdfPageLabels(bytes,startNumber=1,prefix=""){const start=Math.max(1,Math.trunc(Number(startNumber)||1)),pdf=await PDFDocument.load(bytes),count=pdf.getPageCount(),ctx=pdf.context,labelParts={S:PDFName.of("D"),St:PDFNumber.of(start)};if(prefix)labelParts.P=PDFHexString.fromText(String(prefix));const label=ctx.obj(labelParts),nums=ctx.obj([PDFNumber.of(0),label]),pageLabels=ctx.obj({Nums:nums});pdf.catalog.set(PDFName.of("PageLabels"),pageLabels);const output=await pdf.save({useObjectStreams:true}),map=Array.from({length:Math.min(count,1000)},(_,i)=>({page:i+1,label:String(prefix)+(start+i)}));return{page_count:count,start_number:start,prefix:String(prefix),numbering_map:map,numbering_map_truncated:count>map.length,output_bytes:output.length,download:{name:"page-labeled.pdf",bytes:output,type:"application/pdf"}}}
function rows(result){if(!result?.length)return[];const r=result[0];return r.values.map(v=>Object.fromEntries(r.columns.map((c,i)=>[c,v[i]])))}
export async function inspectGeoPackage(bytes,wasmPath){const SQL=await sql(wasmPath),db=new SQL.Database(bytes);try{const names=new Set(rows(db.exec("SELECT name FROM sqlite_master WHERE type='table'")).map(x=>x.name));if(!names.has("gpkg_contents"))throw new Error("SQLite file does not contain the required gpkg_contents table.");const contents=rows(db.exec("SELECT table_name,data_type,identifier,description,last_change,min_x,min_y,max_x,max_y,srs_id FROM gpkg_contents ORDER BY table_name")),geom=names.has("gpkg_geometry_columns")?rows(db.exec("SELECT table_name,column_name,geometry_type_name,srs_id,z,m FROM gpkg_geometry_columns ORDER BY table_name")):[],tile=names.has("gpkg_tile_matrix_set")?rows(db.exec("SELECT table_name,srs_id,min_x,min_y,max_x,max_y FROM gpkg_tile_matrix_set ORDER BY table_name")):[],geomBy=new Map(geom.map(x=>[x.table_name,x])),tileBy=new Map(tile.map(x=>[x.table_name,x])),layers=[];for(const c of contents){let count=null;try{count=Number(rows(db.exec("SELECT COUNT(*) AS n FROM "+qid(c.table_name)))[0]?.n??0)}catch{}layers.push({...c,row_count:count,geometry:geomBy.get(c.table_name)||null,tile_matrix_set:tileBy.get(c.table_name)||null})}const srs=names.has("gpkg_spatial_ref_sys")?rows(db.exec("SELECT srs_name,srs_id,organization,organization_coordsys_id FROM gpkg_spatial_ref_sys ORDER BY srs_id")).slice(0,200):[];return{layer_count:layers.length,layers,spatial_reference_systems:srs,sqlite_tables:names.size}}finally{db.close()}}

const DUCKDB_BASE="/client-tools/vendor/duckdb/";
let duckdbPromise;
const jsonSafe=v=>typeof v==="bigint"?v.toString():v instanceof Date?v.toISOString():ArrayBuffer.isView(v)?Array.from(v):v;
export function validateLocalParquetSql(sqlText){const q=String(sqlText||"").trim().replace(/;\s*$/,"");if(!q)throw new Error("Enter a read-only SQL query.");if(!/^(?:select|with)\b/i.test(q))throw new Error("Only SELECT/WITH queries are allowed.");if(!/\binput\b/i.test(q))throw new Error('Query the local Parquet view named "input".');if(/;/.test(q))throw new Error("Multiple SQL statements are not allowed.");const forbidden=/(?:https?:\/\/|s3:\/\/|gs:\/\/|azure:\/\/|hf:\/\/|\b(?:install|load|attach|detach|copy|export|import|create|insert|update|delete|drop|alter|call|pragma|set|force_install|read_[a-z0-9_]*|parquet_scan|glob|httpfs|shell)\b)/i;if(forbidden.test(q))throw new Error("Remote I/O, extension loading, mutation and file-reading functions are disabled.");return q}
async function localDuckDbWasmUrl(){const mr=await fetch(DUCKDB_BASE+"duckdb-mvp.wasm.parts.json",{cache:"force-cache",credentials:"same-origin"});if(!mr.ok)throw new Error("Local DuckDB WASM manifest is unavailable.");const m=await mr.json();if(!Array.isArray(m.parts)||!Number.isInteger(m.totalBytes)||m.totalBytes<=0)throw new Error("Invalid local DuckDB WASM manifest.");const chunks=[];let total=0;for(const part of m.parts){const url=String(part?.url||""),bytes=Number(part?.bytes);if(!url.startsWith(DUCKDB_BASE+"duckdb-mvp.wasm.part")||!Number.isInteger(bytes)||bytes<=0||bytes>=25*1024*1024)throw new Error("Invalid local DuckDB WASM part.");const r=await fetch(url,{cache:"force-cache",credentials:"same-origin"});if(!r.ok)throw new Error("Local DuckDB WASM part is unavailable.");const b=new Uint8Array(await r.arrayBuffer());if(b.length!==bytes)throw new Error("Local DuckDB WASM part size mismatch.");chunks.push(b);total+=b.length}if(total!==m.totalBytes)throw new Error("Local DuckDB WASM total size mismatch.");return URL.createObjectURL(new Blob(chunks,{type:"application/wasm"}))}
async function localDuckDb(){if(duckdbPromise)return duckdbPromise;duckdbPromise=(async()=>{const wasmUrl=await localDuckDbWasmUrl(),workerUrl=DUCKDB_BASE+"duckdb-browser-mvp.worker.js",worker=new Worker(workerUrl),logger=new duckdb.ConsoleLogger(),db=new duckdb.AsyncDuckDB(logger,worker);try{await db.instantiate(wasmUrl);return{db,wasmUrl}}catch(e){worker.terminate();URL.revokeObjectURL(wasmUrl);duckdbPromise=null;throw e}})();return duckdbPromise}
export async function queryParquet(bytes,sqlText){if(!(bytes instanceof Uint8Array)||bytes.length<12||new TextDecoder().decode(bytes.slice(0,4))!=="PAR1"||new TextDecoder().decode(bytes.slice(-4))!=="PAR1")throw new Error("Not a Parquet file.");const query=validateLocalParquetSql(sqlText),{db}=await localDuckDb(),name="input-"+crypto.randomUUID()+".parquet";let conn;try{await db.registerFileBuffer(name,bytes);conn=await db.connect();await conn.query('CREATE TEMP VIEW input AS SELECT * FROM "'+name.replace(/"/g,'""')+'"');const wrapped="SELECT * FROM ("+query+") AS __aafnai_result LIMIT 1001",table=await conn.query(wrapped),all=table.toArray().map(row=>{const obj=typeof row?.toJSON==="function"?row.toJSON():row;return Object.fromEntries(Object.entries(obj||{}).map(([k,v])=>[k,jsonSafe(v)]))}),truncated=all.length>1000,rows=all.slice(0,1000);return{rows,row_count_returned:rows.length,truncated,columns:(table.schema?.fields||[]).map(f=>({name:f.name,type:String(f.type)})),query,engine:"DuckDB-WASM 1.28.0 · browser-local",note:truncated?"Preview capped at 1,000 rows. Add filters/aggregations for a smaller result.":"Query completed locally in this browser."}}finally{try{if(conn){await conn.query("DROP VIEW IF EXISTS input");await conn.close()}}catch{}try{await db.dropFile(name)}catch{}}}
